Method.Implementation:
Set tStatus = $$$OK
Try {
	If '$IsObject($get(pBatch)) Set tStatus = $$$ERROR($$$ObjectInstanceRequired) Quit
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,"WAE",,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.UnitNumber) {
		Set tStatus = ##class(IHC.ITF.DStruc.HdmAdt.UnitNumber).PutObject(pIOStream,pBatch.UnitNumber,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.Name) {
		Set tStatus = ##class(IHC.ITF.DStruc.HdmAdt.Name).PutObject(pIOStream,pBatch.Name,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.VisitNumber) {
		Set tStatus = ##class(IHC.ITF.DStruc.HdmAdt.VisitNumber).PutObject(pIOStream,pBatch.VisitNumber,0)
		If $$$ISERR(tStatus) Quit
	}
	Do pIOStream.Flush(.tStatus)
	If $$$ISERR(tStatus) Quit
} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,,pTimeout,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set pIOStream.CharEncoding = "UTF-8"
	Set pBatch = ##class(IHC.ITF.DStruc.iSeriesAdtCffToHdmAdtKeyword.Batch).%New()
	Set pBatch.%Source = pIOStream.Name
	Set pLookAhead = $get(pLookAhead)
	If (10 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(10-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,10) = "UnitNum:1|") {
		Set tStatus = ##class(IHC.ITF.DStruc.HdmAdt.UnitNumber).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"UnitNumber","IHC.ITF.DStruc.HdmAdt.UnitNumber",$classname()),tStatus) Quit
		Set pBatch.UnitNumber = tObject
	}
	If (7 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(7-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,7) = "Name:1|") {
		Set tStatus = ##class(IHC.ITF.DStruc.HdmAdt.Name).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"Name","IHC.ITF.DStruc.HdmAdt.Name",$classname()),tStatus) Quit
		Set pBatch.Name = tObject
	}
	If (11 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(11-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,11) = "VisitNum:1|") {
		Set tStatus = ##class(IHC.ITF.DStruc.HdmAdt.VisitNumber).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"VisitNumber","IHC.ITF.DStruc.HdmAdt.VisitNumber",$classname()),tStatus) Quit
		Set pBatch.VisitNumber = tObject
	}
} Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus
